Repair the complete CommonJS module below and return a corrected complete source file.

`tintMask(pixels, color, opacity = 1)` treats `pixels` as consecutive RGBA pixels. It must require a `Uint8ClampedArray` whose length is divisible by four. `color` must be an array of exactly three integer channels from 0 through 255. `opacity` must be a finite number from 0 through 1. Invalid input throws `TypeError`.

Return a new `Uint8ClampedArray`; never mutate or alias the input. For each pixel and each RGB channel, output `Math.round(color[channel] * source[channel] / 255)`. Output alpha is `Math.round(sourceAlpha * opacity)`. Empty pixel data is valid. Export exactly `{ tintMask }`.

```javascript
'use strict';

function tintMask(pixels, color, opacity = 1) {
  if (!(pixels instanceof Uint8ClampedArray) || pixels.length % 4 !== 0) {
    throw new TypeError('invalid pixels');
  }
  if (!Array.isArray(color) || color.length !== 3 ||
      color.some((channel) => !Number.isInteger(channel) || channel < 0 || channel > 255)) {
    throw new TypeError('invalid color');
  }
  if (typeof opacity !== 'number' || !Number.isFinite(opacity) ||
      opacity < 0 || opacity > 1) {
    throw new TypeError('invalid opacity');
  }
  const output = new Uint8ClampedArray(pixels.length);
  for (let index = 0; index < pixels.length; index += 4) {
    output[index] = Math.round(color[0] * pixels[index] / 255);
    output[index + 1] = Math.round(color[2] * pixels[index + 1] / 255);
    output[index + 2] = Math.round(color[2] * pixels[index + 2] / 255);
    output[index + 3] = Math.round(pixels[index + 3] * opacity);
  }
  return output;
}

module.exports = { tintMask };
```

