'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['tintMask']);
const { tintMask } = api;

for (const pixels of [null, [], new Uint8Array(4), new Uint8ClampedArray(3), new Uint8ClampedArray(5)]) {
  assert.throws(() => tintMask(pixels, [1, 2, 3]), TypeError);
}
for (const color of [null, [1, 2], [1, 2, 3, 4], [1, 2, -1], [1, 2, 256], [1, 2, 3.5], ['1', 2, 3]]) {
  assert.throws(() => tintMask(new Uint8ClampedArray(4), color), TypeError);
}
for (const opacity of [-0.1, 1.1, NaN, Infinity, '1', null]) {
  assert.throws(() => tintMask(new Uint8ClampedArray(4), [1, 2, 3], opacity), TypeError);
}
const empty = new Uint8ClampedArray(0);
const emptyResult = tintMask(empty, [0, 255, 128]);
assert.equal(emptyResult instanceof Uint8ClampedArray, true);
assert.equal(emptyResult.length, 0);
assert.notEqual(emptyResult, empty);

const pixels = new Uint8ClampedArray([255, 128, 64, 200, 10, 20, 30, 255]);
const before = new Uint8ClampedArray(pixels);
const result = tintMask(pixels, [100, 50, 200], 0.5);
assert.equal(result instanceof Uint8ClampedArray, true);
assert.notEqual(result, pixels);
assert.deepEqual(Array.from(result), [100, 25, 50, 100, 4, 4, 24, 128]);
assert.deepEqual(pixels, before);
result[0] = 0;
assert.equal(pixels[0], 255);
assert.deepEqual(Array.from(tintMask(new Uint8ClampedArray([255, 255, 255, 255]), [255, 255, 255], 0)), [255, 255, 255, 0]);
assert.deepEqual(Array.from(tintMask(new Uint8ClampedArray([1, 1, 1, 1]), [128, 128, 128], 1)), [1, 1, 1, 1]);

